using System.Security.Cryptography;using System.Text;using System.Text.Json;using Microsoft.EntityFrameworkCore;using PA.Tickets.Application.Tickets;using PA.Tickets.Domain.Tickets;using PA.Tickets.Infrastructure.Execution;using PA.Tickets.Infrastructure.Persistence;
namespace PA.Tickets.Infrastructure.Tickets;
public sealed class EfTicketRepository(TicketsDbContext db,AuditChainCoordinator auditLocks):ITicketRepository
{
 public async Task<Ticket?> GetAsync(long id,CancellationToken ct){var r=await db.Tickets.Include(x=>x.WorkItems).SingleOrDefaultAsync(x=>x.Id==id,ct);return r is null?null:Restore(r,db.Entry(r).Property<int?>("RequestTypeVersion").CurrentValue,db.Entry(r).Property<long?>("SubCategoryId").CurrentValue);}
 public Task AddAsync(Ticket t,CancellationToken ct)=>AddAsync(t,Array.Empty<PA.Tickets.Application.Foundations.TicketFieldValue>(),t.CreatedBy,ct);
 public Task AddAsync(Ticket t,IReadOnlyCollection<PA.Tickets.Application.Foundations.TicketFieldValue> values,long actor,CancellationToken ct)=>AddAsync(t,values,actor,null,ct);
 public async Task AddAsync(Ticket t,IReadOnlyCollection<PA.Tickets.Application.Foundations.TicketFieldValue> values,long actor,string? idempotencyKey,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(ct);if(!string.IsNullOrWhiteSpace(idempotencyKey)){var claim=await db.Set<IdempotencyRow>().SingleOrDefaultAsync(x=>x.Scope=="TICKET_CREATE"&&x.ActorId==actor&&x.Key==idempotencyKey,ct)??throw new KeyNotFoundException("Ticket creation idempotency record was not found.");if(claim.ResultTicketId is long existingTicketId&&existingTicketId!=t.Id)throw new InvalidOperationException("Ticket creation idempotency result does not match the ticket being persisted.");claim.ResultTicketId=t.Id;}var row=ToRow(t);db.Tickets.Add(row);db.Entry(row).Property<int?>("RequestTypeVersion").CurrentValue=t.RequestTypeVersion;db.Entry(row).Property<long?>("SubCategoryId").CurrentValue=t.SubCategoryId;foreach(var w in t.WorkItems)db.WorkItems.Add(ToRow(w,t));foreach(var value in values)db.Set<PA.Tickets.Infrastructure.Foundations.TicketFieldValueRow>().Add(new(){TicketId=t.Id,FieldId=value.FieldId,StringValue=value.StringValue,NumberValue=value.NumberValue,DateValue=value.DateValue,TextValue=value.TextValue,CreatedAt=t.CreatedAt,CreatedBy=actor});await Commit(t,ct);await tx.CommitAsync(ct);}
 public async Task SaveAsync(Ticket t,CancellationToken ct){var r=await db.Tickets.Include(x=>x.WorkItems).SingleAsync(x=>x.Id==t.Id,ct);r.Subject=t.Subject;r.Description=t.Description;r.TypeId=(int)t.Type;r.ServiceId=t.ServiceId;r.CategoryId=t.CategoryId;r.RequestTypeId=t.RequestTypeId;r.ClientId=t.ClientId;r.PriorityId=t.PriorityId;r.StatusId=(int)t.Status;r.CurrentDepartmentId=t.CurrentDepartmentId;r.CurrentTeamId=t.CurrentTeamId;r.CurrentAssignee=t.CurrentAssignee;r.ResolvedAt=t.ResolvedAt;r.ClosedAt=t.ClosedAt;r.EvidenceCount=t.EvidenceCount;r.ApprovalRequired=t.ApprovalRequired?1:0;r.Approved=t.Approved?1:0;r.LastExecutor=t.LastExecutor;db.Entry(r).Property<int?>("RequestTypeVersion").CurrentValue=t.RequestTypeVersion;db.Entry(r).Property<long?>("SubCategoryId").CurrentValue=t.SubCategoryId;foreach(var w in t.WorkItems){var row=r.WorkItems.SingleOrDefault(x=>x.Id==w.Id);if(row is null)db.WorkItems.Add(ToRow(w,t));else Update(row,w);}await Commit(t,ct);}
 public async Task AddRelationshipAsync(TicketRelationship relation,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(ct);if(await db.Relations.AnyAsync(x=>x.TicketId==relation.TicketId&&x.RelatedTicketId==relation.RelatedTicketId&&x.Type==relation.RelationType,ct))throw new InvalidOperationException("The relationship already exists.");db.Relations.Add(new RelationRow{TicketId=relation.TicketId,RelatedTicketId=relation.RelatedTicketId,Type=relation.RelationType,Description=relation.Description,CreatedAt=relation.CreatedAt,CreatedBy=relation.CreatedBy});var ev=new EventRow{TicketId=relation.TicketId,Type="RELATION_CREATED",ActorId=relation.CreatedBy,NewValue=$"{relation.RelatedTicketId}:{relation.RelationType}",Reason=relation.Description,At=relation.CreatedAt};db.Events.Add(ev);await AddAudit("TICKET",relation.TicketId.ToString(),"RELATION_CREATED",relation.CreatedBy,relation.CreatedAt,null,ev.NewValue,relation.Description,ct);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);}
 public async Task<TicketSearchPage> SearchAsync(TicketSearchCriteria c,CancellationToken ct){var q=db.Tickets.AsQueryable();if(!string.IsNullOrWhiteSpace(c.Number))q=q.Where(x=>x.Number.Contains(c.Number));if(c.Status is not null)q=q.Where(x=>x.StatusId==(int)c.Status);if(c.Type is not null)q=q.Where(x=>x.TypeId==(int)c.Type);if(c.PriorityId is not null)q=q.Where(x=>x.PriorityId==c.PriorityId);if(c.ServiceId is not null)q=q.Where(x=>x.ServiceId==c.ServiceId);if(c.CategoryId is not null)q=q.Where(x=>x.CategoryId==c.CategoryId);if(c.RequestTypeId is not null)q=q.Where(x=>x.RequestTypeId==c.RequestTypeId);if(c.ClientId is not null)q=q.Where(x=>x.ClientId==c.ClientId);if(c.DepartmentId is not null)q=q.Where(x=>x.CurrentDepartmentId==c.DepartmentId);if(c.TeamId is not null)q=q.Where(x=>x.CurrentTeamId==c.TeamId);if(c.AssigneeId is not null)q=q.Where(x=>x.CurrentAssignee==c.AssigneeId);if(c.CreatedFrom is not null)q=q.Where(x=>x.CreatedAt>=c.CreatedFrom);if(c.CreatedTo is not null)q=q.Where(x=>x.CreatedAt<=c.CreatedTo);var total=await q.CountAsync(ct);var page=Math.Max(1,c.Page);var size=Math.Clamp(c.PageSize,1,100);var rows=await q.OrderByDescending(x=>x.CreatedAt).Skip((page-1)*size).Take(size).ToListAsync(ct);return new(rows.Select(x=>ToView(x,db.Entry(x).Property<int?>("RequestTypeVersion").CurrentValue,db.Entry(x).Property<long?>("SubCategoryId").CurrentValue)).ToArray(),page,size,total);}
 private async Task Commit(Ticket t,CancellationToken ct){var ownsTransaction=db.Database.CurrentTransaction is null;await using var tx=ownsTransaction?await db.Database.BeginTransactionAsync(ct):null;foreach(var e in t.UncommittedEvents){db.Events.Add(new EventRow{TicketId=t.Id,WorkItemId=e.WorkItemId,Type=e.Action,ActorId=e.ActorUserId,OldValue=e.OldValue,NewValue=e.NewValue,Reason=e.Reason,At=e.OccurredAt});if(e.Action is "WORK_ITEM_ASSIGNED" or "WORK_ITEM_REASSIGNED")db.Assignments.Add(new AssignmentRow{TicketId=t.Id,WorkItemId=e.WorkItemId,AssignedTo=long.TryParse(e.NewValue,out var assigned)?assigned:null,Type="WORK_ITEM",AssignedAt=e.OccurredAt,AssignedBy=e.ActorUserId,Reason=e.Reason});await AddAudit("TICKET",t.Id.ToString(),e.Action,e.ActorUserId,e.OccurredAt,e.OldValue,e.NewValue,e.Reason,ct);}await db.SaveChangesAsync(ct);if(tx is not null)await tx.CommitAsync(ct);t.ClearEvents();}
 private async Task AddAudit(string entityType,string entityId,string action,long actor,DateTimeOffset at,string? oldValue,string? newValue,string? reason,CancellationToken ct){await auditLocks.AcquireAsync(db,entityType,entityId,ct);var utcTicks=at.UtcDateTime.Ticks;at=new DateTimeOffset(utcTicks-utcTicks%10,TimeSpan.Zero);var previous=await db.Audits.Where(x=>x.EntityType==entityType&&x.EntityId==entityId).OrderByDescending(x=>x.Id).Select(x=>x.Hash).FirstOrDefaultAsync(ct);var canonical=JsonSerializer.Serialize(new{entityType,entityId,action,actorUserId=actor,auditAtUtc=at.UtcDateTime,oldValue,newValue,reason,previousHash=previous});var hash=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(canonical))).ToLowerInvariant();db.Audits.Add(new AuditRow{EntityType=entityType,EntityId=entityId,Action=action,ActorId=actor,At=at,OldValue=oldValue,NewValue=newValue,Reason=reason,Hash=hash,PreviousHash=previous});}
 private static TicketRow ToRow(Ticket t)=>new(){Id=t.Id,Number=t.Number,TypeId=(int)t.Type,ServiceId=t.ServiceId,CategoryId=t.CategoryId,RequestTypeId=t.RequestTypeId,ClientId=t.ClientId,RequestedBy=t.RequestedBy,Subject=t.Subject,Description=t.Description,PriorityId=t.PriorityId,StatusId=(int)t.Status,CurrentDepartmentId=t.CurrentDepartmentId,CurrentTeamId=t.CurrentTeamId,CreatedAt=t.CreatedAt,CreatedBy=t.CreatedBy,EvidenceCount=t.EvidenceCount,ApprovalRequired=t.ApprovalRequired?1:0,Approved=t.Approved?1:0,LastExecutor=t.LastExecutor};
 private static WorkItemRow ToRow(WorkItem w,Ticket t)=>new(){Id=w.Id,TicketId=t.Id,Number=w.Number,PublicId=w.PublicId,ToDepartmentId=w.ToDepartmentId,ToTeamId=w.ToTeamId,AssignedToUserId=w.AssignedToUserId,PriorityId=w.PriorityId,Status=w.Status,WaitingFor=w.WaitingFor,WaitingComment=w.WaitingComment,WaitingEvidenceReference=w.WaitingEvidenceReference,WaitingExpectedDate=w.WaitingExpectedDate,WaitingMinutes=w.WaitingMinutes,WaitingStartedAt=w.WaitingStartedAt,WaitingResumedAt=w.WaitingResumedAt,StartedAt=w.StartedAt,CompletedAt=w.CompletedAt,CreatedAt=t.CreatedAt,CreatedBy=t.CreatedBy};
 private static void Update(WorkItemRow r,WorkItem w){r.ToDepartmentId=w.ToDepartmentId;r.ToTeamId=w.ToTeamId;r.AssignedToUserId=w.AssignedToUserId;r.PriorityId=w.PriorityId;r.Status=w.Status;r.WaitingFor=w.WaitingFor;r.WaitingComment=w.WaitingComment;r.WaitingEvidenceReference=w.WaitingEvidenceReference;r.WaitingExpectedDate=w.WaitingExpectedDate;r.WaitingMinutes=w.WaitingMinutes;r.WaitingStartedAt=w.WaitingStartedAt;r.WaitingResumedAt=w.WaitingResumedAt;r.StartedAt=w.StartedAt;r.CompletedAt=w.CompletedAt;}
 private static Ticket Restore(TicketRow r,int? requestTypeVersion,long? subCategoryId)=>Ticket.Restore(r.Id,r.Number,(TicketType)r.TypeId,(TicketStatus)r.StatusId,r.RequestedBy,r.CreatedBy,r.Subject,r.Description,r.ServiceId,r.CategoryId,r.RequestTypeId,r.PriorityId,r.CurrentDepartmentId,r.CurrentTeamId,r.CurrentAssignee,r.CreatedAt,r.ResolvedAt,r.ClosedAt,r.ApprovalRequired==1,r.Approved==1,r.EvidenceCount,r.LastExecutor,r.WorkItems.Select(w=>WorkItem.Restore(w.Id,w.TicketId,w.Number,w.ToDepartmentId,w.ToTeamId,w.AssignedToUserId,w.PriorityId,w.Status,w.WaitingFor,w.WaitingComment,w.WaitingEvidenceReference,w.WaitingExpectedDate,w.WaitingStartedAt,w.WaitingResumedAt,w.WaitingMinutes,w.StartedAt,w.CompletedAt,w.PublicId)),r.ClientId,requestTypeVersion,subCategoryId);
 private static TicketView ToView(TicketRow r,int? requestTypeVersion,long? subCategoryId)=>new(r.Id,r.Number,(TicketType)r.TypeId,(TicketStatus)r.StatusId,r.Subject,r.PriorityId,r.CurrentDepartmentId,r.CurrentTeamId,r.CurrentAssignee,Array.Empty<WorkItemView>(),r.ServiceId,r.CategoryId,subCategoryId,r.RequestTypeId,requestTypeVersion);
}
